import Foundation
import Crypto
import NIO
import NIOHTTP1

// CI/CD Pipeline Artifact Decryption Service
// Handles encrypted build artifacts passed between pipeline stages

actor DecryptionOracle {
    private let key: SymmetricKey
    private var requestLog: [(Date, String, Bool)] = []
    private let blockSize = 16

    init(keyData: Data) {
        self.key = SymmetricKey(data: keyData)
    }

    // Decrypt artifact payload using AES-CBC
    func decryptArtifact(encryptedPayload: Data, iv: Data, requestId: String) async throws -> Data {
        let startTime = ContinuousClock.now

        guard iv.count == blockSize else {
            throw DecryptionError.invalidIV
        }
        guard encryptedPayload.count % blockSize == 0 else {
            throw DecryptionError.invalidCiphertext
        }

        let decrypted = try aesCBCDecrypt(data: encryptedPayload, key: key, iv: iv)

        // Validate PKCS7 padding
        let paddingResult = validateAndStripPadding(decrypted)

        let elapsed = ContinuousClock.now - startTime

        switch paddingResult {
        case .success(let plaintext):
            requestLog.append((Date(), requestId, true))
            return plaintext
        case .failure(let error):
            requestLog.append((Date(), requestId, false))
            throw error
        }
    }

    // Pipeline stage token verification with decryption
    func verifyStageToken(token: Data, iv: Data, expectedStage: String) async throws -> Bool {
        let decrypted: Data
        do {
            decrypted = try await decryptArtifact(encryptedPayload: token, iv: iv, requestId: "stage-verify")
        } catch DecryptionError.invalidPadding {
            // Return specific error for padding failures
            throw DecryptionError.invalidPadding
        } catch {
            throw DecryptionError.decryptionFailed
        }

        guard let stageString = String(data: decrypted, encoding: .utf8) else {
            throw DecryptionError.invalidPayload
        }
        return stageString.hasPrefix(expectedStage)
    }

    private func validateAndStripPadding(_ data: Data) -> Result<Data, DecryptionError> {
        guard let lastByte = data.last else {
            return .failure(.invalidPadding)
        }

        let paddingLength = Int(lastByte)

        if paddingLength == 0 || paddingLength > blockSize {
            return .failure(.invalidPadding)
        }

        if paddingLength > data.count {
            return .failure(.invalidPadding)
        }

        let paddingStart = data.count - paddingLength
        for i in paddingStart..<data.count {
            if data[i] != lastByte {
                return .failure(.invalidPadding)
            }
        }

        return .success(data.prefix(paddingStart))
    }

    private func aesCBCDecrypt(data: Data, key: SymmetricKey, iv: Data) throws -> Data {
        // AES-CBC decryption implementation
        var previousBlock = iv
        var result = Data()

        for blockStart in stride(from: 0, to: data.count, by: blockSize) {
            let block = data[blockStart..<blockStart + blockSize]
            let decryptedBlock = try aesECBDecryptBlock(Data(block), key: key)
            let xored = xorBlocks(decryptedBlock, Data(previousBlock))
            result.append(xored)
            previousBlock = Data(block)
        }

        return result
    }

    private func aesECBDecryptBlock(_ block: Data, key: SymmetricKey) throws -> Data {
        // Wrapper around platform AES-ECB single block decryption
        let sealedBox = try AES.GCM.open(AES.GCM.SealedBox(combined: block + Data(repeating: 0, count: 28)), using: key)
        return sealedBox
    }

    private func xorBlocks(_ a: Data, _ b: Data) -> Data {
        Data(zip(a, b).map { $0 ^ $1 })
    }
}

enum DecryptionError: Error, Equatable {
    case invalidIV
    case invalidCiphertext
    case invalidPadding
    case decryptionFailed
    case invalidPayload
    case authenticationFailed
}

// HTTP Handler for the CI/CD pipeline service
final class PipelineHandler: ChannelInboundHandler {
    typealias InboundIn = HTTPServerRequestPart

    private let oracle: DecryptionOracle

    init(oracle: DecryptionOracle) {
        self.oracle = oracle
    }

    func channelRead(context: ChannelHandlerContext, data: NIOAny) {
        let reqPart = unwrapInboundIn(data)

        switch reqPart {
        case .body(let buffer):
            guard let bytes = buffer.getBytes(at: 0, length: buffer.readableBytes) else { return }
            let payload = Data(bytes)

            Task {
                do {
                    let iv = payload.prefix(16)
                    let ciphertext = payload.dropFirst(16)
                    let result = try await oracle.decryptArtifact(
                        encryptedPayload: Data(ciphertext),
                        iv: Data(iv),
                        requestId: UUID().uuidString
                    )
                    // Send 200 with decrypted artifact
                    self.sendResponse(context: context, status: .ok, body: result)
                } catch DecryptionError.invalidPadding {
                    // Padding error - return 400
                    self.sendResponse(context: context, status: .badRequest, body: Data("Bad padding".utf8))
                } catch {
                    // Other errors - return 500
                    self.sendResponse(context: context, status: .internalServerError, body: Data("Error".utf8))
                }
            }
        default:
            break
        }
    }

    private func sendResponse(context: ChannelHandlerContext, status: HTTPResponseStatus, body: Data) {
        var headers = HTTPHeaders()
        headers.add(name: "Content-Type", value: "application/octet-stream")
        headers.add(name: "Content-Length", value: "\(body.count)")
        let head = HTTPResponseHead(version: .http1_1, status: status, headers: headers)
        context.write(self.wrapOutboundOut(.head(head)), promise: nil)
        var buffer = context.channel.allocator.buffer(capacity: body.count)
        buffer.writeBytes(body)
        context.write(self.wrapOutboundOut(.body(.byteBuffer(buffer))), promise: nil)
        context.writeAndFlush(self.wrapOutboundOut(.end(nil)), promise: nil)
    }
}
